use super::Clipboard;
use anyhow::{Result, ensure};
use objc2::rc::{Retained, autoreleasepool};
use objc2_app_kit::{NSPasteboard, NSPasteboardAccessBehavior, NSPasteboardTypeString};
use objc2_foundation::{NSArray, NSString};

/// Types that mark content as not for syncing, per nspasteboard.org. Password
/// managers set these.
const SKIPPED_TYPES: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];

/// `name` selects a private pasteboard, which lets tests avoid the real clipboard.
pub struct MacClipboard {
    name: Option<String>,
}

impl MacClipboard {
    pub fn new(name: Option<String>) -> Self {
        Self { name }
    }

    fn board(&self) -> Retained<NSPasteboard> {
        match &self.name {
            Some(name) => NSPasteboard::pasteboardWithName(&NSString::from_str(name)),
            None => NSPasteboard::generalPasteboard(),
        }
    }
}

impl Clipboard for MacClipboard {
    fn change_token(&self) -> u64 {
        autoreleasepool(|_| self.board().changeCount() as u64)
    }

    fn read_text(&self) -> Result<Option<String>> {
        Ok(autoreleasepool(|_| {
            let board = self.board();
            let types: Option<Retained<NSArray<NSString>>> = board.types();
            let skipped = types.is_some_and(|types| {
                types
                    .iter()
                    .any(|t| SKIPPED_TYPES.contains(&t.to_string().as_str()))
            });
            if skipped {
                return None;
            }
            board
                .stringForType(unsafe { NSPasteboardTypeString })
                .map(|text| text.to_string())
        }))
    }

    fn write_text(&self, text: &str) -> Result<()> {
        let wrote = autoreleasepool(|_| {
            let board = self.board();
            board.clearContents();
            board.setString_forType(&NSString::from_str(text), unsafe {
                NSPasteboardTypeString
            })
        });
        ensure!(wrote, "the pasteboard refused the write");
        Ok(())
    }

    fn startup_note(&self) -> Option<String> {
        if self.name.is_some() {
            return None;
        }
        let behavior = autoreleasepool(|_| self.board().accessBehavior());
        const SETTINGS: &str = "System Settings > Privacy & Security > Paste from Other Apps";
        if behavior == NSPasteboardAccessBehavior::AlwaysDeny {
            Some(format!(
                "macOS is denying clipboard access, so copies here won't sync. Allow it in {SETTINGS}."
            ))
        } else if behavior == NSPasteboardAccessBehavior::AlwaysAllow {
            None
        } else {
            Some(format!(
                "macOS will ask before each clipboard read. Choose Always Allow, or change it in {SETTINGS}."
            ))
        }
    }
}
